INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11401, 'ក្នុងត្រីកោណកែង \(ABC\) កែងត្រង់ \(C\) តើផលធៀបត្រីកោណមាត្រ \(\sin A\) ស្មើនឹងអ្វី?', 'g10-d00ed2af10.svg', '["\\(\\dfrac{BC}{AB}\\)", "\\(\\dfrac{AC}{AB}\\)", "\\(\\dfrac{AC}{BC}\\)", "\\(\\dfrac{BC}{AC}\\)"]', 0, NULL, 1, 'mcq', '\sin A = \frac{BC}{AB}', 'ផលធៀបត្រីកោណមាត្រ', 'easy', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11402, 'តើតម្លៃនៃ \(\sin 30^\circ\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{\\sqrt{3}}{2}\\)", "\\(1\\)", "\\(\\dfrac{\\sqrt{2}}{2}\\)", "\\(\\dfrac{1}{2}\\)"]', 3, NULL, 1, 'mcq', '\sin 30^\circ = \frac{1}{2}', 'ផលធៀបត្រីកោណមាត្រ', 'easy', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11403, 'ចំពោះគ្រប់មុំស្រួច \(\alpha\) តើរូបមន្តគ្រឹះត្រីកោណមាត្រមួយណាត្រឹមត្រូវ?', NULL, '["\\(\\sin \\alpha + \\cos \\alpha = 1\\)", "\\(\\tan^2 \\alpha + \\cot^2 \\alpha = 1\\)", "\\(\\sin^2 \\alpha + \\cos^2 \\alpha = 1\\)", "\\(\\sin^2 \\alpha - \\cos^2 \\alpha = 1\\)"]', 2, NULL, 1, 'mcq', '\sin^2 \alpha + \cos^2 \alpha = 1', 'ផលធៀបត្រីកោណមាត្រ', 'easy', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
