INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11404, 'នៅលើរង្វង់ត្រីកោណមាត្រ ចំណុច \(M(\alpha)\) មានកូអរដោនេ \((x, y)\)។ តើអាប់ស៊ីស \(x\) តំណាងឱ្យផលធៀបអ្វី?', 'g10-9505ffc836.svg', '["\\(\\tan \\alpha\\)", "\\(\\cot \\alpha\\)", "\\(\\sin \\alpha\\)", "\\(\\cos \\alpha\\)"]', 3, NULL, 1, 'mcq', 'x = \cos \alpha', 'ផលធៀបត្រីកោណមាត្រ', 'easy', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11405, 'តើតម្លៃនៃ \(\sin 150^\circ\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(-\\dfrac{\\sqrt{3}}{2}\\)", "\\(\\dfrac{\\sqrt{3}}{2}\\)", "\\(\\dfrac{1}{2}\\)", "\\(-\\dfrac{1}{2}\\)"]', 2, NULL, 1, 'mcq', '\sin 150^\circ = \sin(180^\circ - 30^\circ) = \sin 30^\circ = \frac{1}{2}', 'ផលធៀបត្រីកោណមាត្រ', 'easy', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
