INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11411, 'ក្នុងត្រីកោណកែង \(ABC\) កែងត្រង់ \(C\) មាន \(AC = 6\text{ cm}\) និង \(BC = 8\text{ cm}\)។ គណនា \(\sin A\)។', NULL, '["\\(\\dfrac{3}{4}\\)", "\\(\\dfrac{4}{5}\\)", "\\(\\dfrac{4}{3}\\)", "\\(\\dfrac{3}{5}\\)"]', 1, NULL, 2, 'mcq', 'AB = 10 \implies \sin A = \frac{8}{10} = \frac{4}{5}', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
