INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11419, 'បើ \(\tan \alpha = 2\) គណនាតម្លៃនៃកន្សោម \(E = \dfrac{\sin \alpha + 3\cos \alpha}{2\sin \alpha - \cos \alpha}\)។', NULL, '["\\(\\dfrac{5}{3}\\)", "\\(1\\)", "\\(2\\)", "\\(\\dfrac{7}{3}\\)"]', 0, NULL, 2, 'mcq', 'E = \frac{\tan \alpha + 3}{2\tan \alpha - 1} = \frac{2 + 3}{4 - 1} = \frac{5}{3}', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11420, 'តើតម្លៃនៃ \(\tan 135^\circ\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(1\\)", "\\(-\\dfrac{\\sqrt{3}}{3}\\)", "\\(-\\sqrt{3}\\)", "\\(-1\\)"]', 3, NULL, 2, 'mcq', '\tan 135^\circ = -\tan 45^\circ = -1', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11421, 'ក្នុងត្រីកោណកែង \(ABC\) កែងត្រង់ \(C\) មាន \(\angle A = 30^\circ\) និងអ៊ីប៉ូតេនុស \(AB = 12\text{ cm}\)។ រកប្រវែងជ្រុង \(BC\)។', NULL, '["\\(6\\text{ cm}\\)", "\\(4\\text{ cm}\\)", "\\(6\\sqrt{3}\\text{ cm}\\)", "\\(8\\text{ cm}\\)"]', 0, NULL, 2, 'mcq', 'BC = 12 \sin 30^\circ = 6\text{ cm}', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11422, 'សម្រួលកន្សោម \(P = (\sin \alpha + \cos \alpha)^2 + (\sin \alpha - \cos \alpha)^2\)។', NULL, '["\\(0\\)", "\\(4\\sin \\alpha \\cos \\alpha\\)", "\\(1\\)", "\\(2\\)"]', 3, NULL, 2, 'mcq', 'P = (1 + 2\sin \alpha \cos \alpha) + (1 - 2\sin \alpha \cos \alpha) = 2', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11423, 'តើតម្លៃនៃ \(\sin 135^\circ\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(-\\dfrac{\\sqrt{2}}{2}\\)", "\\(\\dfrac{\\sqrt{2}}{2}\\)", "\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{\\sqrt{3}}{2}\\)"]', 1, NULL, 2, 'mcq', '\sin 135^\circ = \sin 45^\circ = \frac{\sqrt{2}}{2}', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11424, 'សម្រួលកន្សោម \(Q = \dfrac{1}{1 + \sin \alpha} + \dfrac{1}{1 - \sin \alpha}\)។', NULL, '["\\(\\dfrac{2}{1 - \\sin \\alpha}\\)", "\\(\\dfrac{2}{\\sin^2 \\alpha}\\)", "\\(\\dfrac{2}{\\cos^2 \\alpha}\\)", "\\(\\dfrac{1}{\\cos^2 \\alpha}\\)"]', 2, NULL, 2, 'mcq', 'Q = \frac{2}{1 - \sin^2 \alpha} = \frac{2}{\cos^2 \alpha}', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11425, 'គេឱ្យ \(\sin \alpha + \cos \alpha = \dfrac{7}{5}\)។ គណនាតម្លៃនៃ \(\sin \alpha \cos \alpha\)។', NULL, '["\\(\\dfrac{24}{25}\\)", "\\(\\dfrac{6}{25}\\)", "\\(\\dfrac{7}{25}\\)", "\\(\\dfrac{12}{25}\\)"]', 3, NULL, 3, 'mcq', '1 + 2\sin \alpha \cos \alpha = 49/25 \implies \sin \alpha \cos \alpha = 12/25', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11426, 'ដោះស្រាយសមីការ \(2\sin^2 x - 3\sin x + 1 = 0\) ចំពោះមុំស្រួច \(0^\circ \le x \le 90^\circ\)។', NULL, '["\\(x = 60^\\circ \\text{ ឬ } x = 90^\\circ\\)", "\\(x = 30^\\circ \\text{ តែមួយគត់}\\)", "\\(x = 45^\\circ \\text{ ឬ } x = 30^\\circ\\)", "\\(x = 30^\\circ \\text{ ឬ } x = 90^\\circ\\)"]', 3, NULL, 3, 'mcq', '\sin x = 1/2 \implies x = 30^\circ; \sin x = 1 \implies x = 90^\circ', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11427, 'បើ \(\sin \alpha = \dfrac{3}{5}\) និង \(90^\circ < \alpha < 180^\circ\) នោះតម្លៃនៃ \(\cos \alpha\) និង \(\tan \alpha\) ស្មើនឹង ៖', NULL, '["\\(\\cos \\alpha = -\\dfrac{3}{4},\\; \\tan \\alpha = -\\dfrac{4}{3}\\)", "\\(\\cos \\alpha = -\\dfrac{4}{5},\\; \\tan \\alpha = -\\dfrac{3}{4}\\)", "\\(\\cos \\alpha = \\dfrac{4}{5},\\; \\tan \\alpha = \\dfrac{3}{4}\\)", "\\(\\cos \\alpha = -\\dfrac{4}{5},\\; \\tan \\alpha = \\dfrac{3}{4}\\)"]', 1, NULL, 3, 'mcq', '\cos \alpha = -4/5, \tan \alpha = -3/4', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11428, 'បំបាត់ \(\alpha\) ពីប្រព័ន្ធ \(x = 3 + 2\cos \alpha,\; y = -1 + 2\sin \alpha\)។', NULL, '["\\((x - 3)^2 + (y + 1)^2 = 2\\)", "\\((x + 3)^2 + (y - 1)^2 = 4\\)", "\\((x - 3)^2 - (y + 1)^2 = 4\\)", "\\((x - 3)^2 + (y + 1)^2 = 4\\)"]', 3, NULL, 3, 'mcq', '(x - 3)^2 + (y + 1)^2 = 4', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11429, 'គេឱ្យ \(\tan \alpha + \cot \alpha = 3\)។ គណនាតម្លៃនៃ \(\tan^2 \alpha + \cot^2 \alpha\)។', NULL, '["\\(5\\)", "\\(7\\)", "\\(11\\)", "\\(9\\)"]', 1, NULL, 3, 'mcq', '\tan^2 \alpha + \cot^2 \alpha = 3^2 - 2 = 7', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11430, 'សម្រួលកន្សោម \(M = \sqrt{\sin^4 \alpha + 4\cos^2 \alpha} + \sqrt{\cos^4 \alpha + 4\sin^2 \alpha}\)។', NULL, '["\\(3\\)", "\\(4\\)", "\\(1\\)", "\\(2\\)"]', 0, NULL, 3, 'mcq', '(2 - \sin^2 \alpha) + (2 - \cos^2 \alpha) = 4 - 1 = 3', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11431, 'គេឱ្យ \(\sin \alpha - \cos \alpha = \dfrac{1}{3}\)។ គណនាតម្លៃនៃ \(\sin \alpha \cos \alpha\)។', NULL, '["\\(\\dfrac{2}{9}\\)", "\\(\\dfrac{1}{9}\\)", "\\(\\dfrac{4}{9}\\)", "\\(\\dfrac{8}{9}\\)"]', 2, NULL, 3, 'mcq', '1 - 2\sin \alpha \cos \alpha = 1/9 \implies \sin \alpha \cos \alpha = 4/9', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
