INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11432, 'បង្គោលទង់ជាតិមួយមានកម្ពស់ \(8\text{ m}\) ចោលស្រមោលលើដីរាបស្មើមានប្រវែង \(8\sqrt{3}\text{ m}\)។ តើមុំងើបនៃព្រះអាទិត្យធៀបនឹងដីរាបស្មើស្មើនឹងប៉ុន្មាន?', 'g10-fdb6be0322.svg', '["\\(60^\\circ\\)", "\\(45^\\circ\\)", "\\(75^\\circ\\)", "\\(30^\\circ\\)"]', 3, NULL, 3, 'mcq', '\tan \theta = 1/\sqrt{3} \implies \theta = 30^\circ', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11433, 'ផ្លូវជម្រាលសម្រាប់ជនពិការត្រូវសាងសង់ដោយមុំជម្រាលមិនឱ្យលើសពី \(5^\circ\) ឡើយ។ បើកម្រិតកម្ពស់មាត់ទ្វារធៀបនឹងដីគឺ \(0.6\text{ m}\) គណនាប្រវែងជម្រាល \(L\) យ៉ាងតិចបំផុត (យក \(\sin 5^\circ \approx 0.0872\))។', NULL, '["\\(\\approx 8.40\\text{ m}\\)", "\\(\\approx 6.88\\text{ m}\\)", "\\(\\approx 4.50\\text{ m}\\)", "\\(\\approx 5.25\\text{ m}\\)"]', 1, NULL, 3, 'mcq', 'L = 0.6 / 0.0872 \approx 6.88\text{ m}', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11434, 'សុភ័ក្ត្របង្ហោះខ្លែងមួយដោយប្រើខ្សែប្រវែង \(100\text{ m}\) តឹងត្រង់ ដោយបង្កើតបានមុំ \(45^\circ\) ធៀបនឹងដីរាបស្មើ។ បើដៃគាត់កាន់ខ្សែខ្លែងខ្ពស់ពីដី \(1.2\text{ m}\) តើខ្លែងកំពុងហោះនៅកម្ពស់ប៉ុន្មានពីដី? (យក \(\sqrt{2} \approx 1.414\))', NULL, '["\\(\\approx 85.2\\text{ m}\\)", "\\(\\approx 65.5\\text{ m}\\)", "\\(\\approx 70.7\\text{ m}\\)", "\\(\\approx 71.9\\text{ m}\\)"]', 3, NULL, 3, 'mcq', 'h = 100 \times \frac{\sqrt{2}}{2} + 1.2 \approx 71.9\text{ m}', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11435, 'ផ្ទាំងសូឡាមួយប្រវែង \(2.0\text{ m}\) តាមបណ្តោយជម្រាល ត្រូវបានដំឡើងទ្រេតមុំ \(15^\circ\) ធៀបនឹងដំបូលរាបស្មើ។ គណនាកម្ពស់បញ្ឈរនៃគែមខាងលើធៀបនឹងបាតក្រោម (យក \(\sin 15^\circ \approx 0.2588\))។', NULL, '["\\(\\approx 51.8\\text{ cm}\\)", "\\(\\approx 38.6\\text{ cm}\\)", "\\(\\approx 45.0\\text{ cm}\\)", "\\(\\approx 62.4\\text{ cm}\\)"]', 0, NULL, 3, 'mcq', 'h = 2.0 \times 0.2588 = 0.5176\text{ m} \approx 51.8\text{ cm}', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11436, 'ដ្រូនមួយកំពុងហោះត្រង់ពីលើចំណុច \(H\) លើដីនៅកម្ពស់ \(60\text{ m}\)។ អ្នកបញ្ជាឈរនៅចំណុច \(P\) លើដីសម្លឹងមើលដ្រូនឃើញមុំងើប \(60^\circ\)។ គណនាចម្ងាយខ្សែភ្នែកពីអ្នកបញ្ជាទៅដ្រូន។', NULL, '["\\(120\\text{ m}\\)", "\\(40\\sqrt{3}\\text{ m}\\)", "\\(30\\sqrt{3}\\text{ m}\\)", "\\(60\\sqrt{3}\\text{ m}\\)"]', 1, NULL, 3, 'mcq', 'd = 60 / \sin 60^\circ = 40\sqrt{3}\text{ m}', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 1, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11437, 'ក្នុងត្រីកោណកែង \(ABC\) កែងត្រង់ \(C\) មានរង្វាស់ជ្រុង \(BC = 5\text{ cm}\) និង \(AC = 12\text{ cm}\)។
ក. គណនាប្រវែងអ៊ីប៉ូតេនុស \(AB\)។
ខ. គណនាផលធៀបត្រីកោណមាត្រទាំងបួននៃមុំ \(A\) (\(\sin A, \cos A, \tan A, \cot A\))។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តទ្រឹស្តីបទពីតាករ: AB = sqrt(AC^2 + BC^2) = sqrt(144 + 25) = sqrt(169) = 13 cm (1.5 ពិន្ទុ)
គណនា sin A = BC / AB = 5 / 13 (1 ពិន្ទុ)
គណនា cos A = AC / AB = 12 / 13 (1 ពិន្ទុ)
គណនា tan A = BC / AC = 5 / 12 (1 ពិន្ទុ)
គណនា cot A = AC / BC = 12 / 5 (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'easy', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11438, 'គេឱ្យ \(\cos \alpha = -\dfrac{3}{5}\) ដោយដឹងថា \(90^\circ < \alpha < 180^\circ\)។
ក. គណនាតម្លៃនៃ \(\sin \alpha\), \(\tan \alpha\) និង \(\cot \alpha\)។
ខ. គណនាតម្លៃនៃកន្សោម \(A = \dfrac{\sin \alpha - 2\cos \alpha}{\tan \alpha + \cot \alpha}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា sin α: ក្នុងកាដ្រង់ទី 2, sin α > 0 នាំឱ្យ sin α = sqrt(1 - (-3/5)^2) = sqrt(16/25) = 4/5 (1.5 ពិន្ទុ)
គណនា tan α = sin α / cos α = (4/5) / (-3/5) = -4/3 និង cot α = -3/4 (1 ពិន្ទុ)
គណនាភាគយក: sin α - 2 cos α = 4/5 - 2(-3/5) = 4/5 + 6/5 = 10/5 = 2 (1 ពិន្ទុ)
គណនាភាគបែង: tan α + cot α = -4/3 - 3/4 = (-16 - 9) / 12 = -25/12 (1 ពិន្ទុ)
សន្និដ្ឋានតម្លៃ A = 2 / (-25/12) = -24/25 (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11439, 'គណនាតម្លៃប្រាកដនៃកន្សោមត្រីកោណមាត្រខាងក្រោម ៖
\(M = 4\cos^2 30^\circ - 3\tan 45^\circ + 2\sin 60^\circ \tan 30^\circ - \cos 180^\circ\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស cos 30° = sqrt(3)/2 នាំឱ្យ 4 cos^2 30° = 4(3/4) = 3 (1.5 ពិន្ទុ)
ជំនួស tan 45° = 1 នាំឱ្យ -3 tan 45° = -3 (1 ពិន្ទុ)
ជំនួស sin 60° = sqrt(3)/2 និង tan 30° = sqrt(3)/3 នាំឱ្យ 2(sqrt(3)/2)(sqrt(3)/3) = 1 (1 ពិន្ទុ)
ជំនួស cos 180° = -1 នាំឱ្យ -cos 180° = -(-1) = 1 (1 ពិន្ទុ)
បូកបញ្ចូលគ្នា: M = 3 - 3 + 1 + 1 = 2 (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11440, 'ក. ស្រាយបញ្ជាក់សមភាពត្រីកោណមាត្រ ៖ \(\dfrac{1 - \cos \alpha}{\sin \alpha} = \dfrac{\sin \alpha}{1 + \cos \alpha}\)។
ខ. ទាញរកតម្លៃសម្រួលនៃកន្សោម \(S = \dfrac{1 - \cos \alpha}{\sin \alpha} + \dfrac{\sin \alpha}{1 - \cos \alpha}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គុណខ្វែងត្រួតពិនិត្យ: (1 - cos α)(1 + cos α) = 1 - cos^2 α (1 ពិន្ទុ)
ប្រើរូបមន្តគ្រឹះ 1 - cos^2 α = sin^2 α = sin α * sin α នាំឱ្យសមភាពទីមួយពិត (1.5 ពិន្ទុ)
តម្រូវភាគបែងកន្សោម S: ភាគបែងរួមគឺ sin α (1 - cos α) (1 ពិន្ទុ)
គណនាភាគយក: (1 - cos α)^2 + sin^2 α = 1 - 2cos α + cos^2 α + sin^2 α = 2 - 2cos α = 2(1 - cos α) (1 ពិន្ទុ)
សម្រួលតួ (1 - cos α): S = 2(1 - cos α) / [sin α (1 - cos α)] = 2 / sin α (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11441, 'ក្នុងត្រីកោណកែង \(ABC\) កែងត្រង់ \(C\) មាន \(AB = 10\text{ cm}\) និងមុំ \(\angle A = 30^\circ\)។
ក. គណនាប្រវែងជ្រុង \(BC\) និង \(AC\)។
ខ. គណនាប្រវែងកម្ពស់ \(CH\) គូសចេញពីកំពូល \(C\) មកលើអ៊ីប៉ូតេនុស \(AB\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា BC = AB * sin 30° = 10 * (1/2) = 5 cm (1.5 ពិន្ទុ)
គណនា AC = AB * cos 30° = 10 * (sqrt(3)/2) = 5 sqrt(3) cm (1.5 ពិន្ទុ)
ប្រើរូបមន្តផ្ទៃក្រឡា: S = (1/2) * AC * BC = (1/2) * CH * AB (1 ពិន្ទុ)
ទាញរក CH = (AC * BC) / AB = (5 * 5 sqrt(3)) / 10 = 2.5 sqrt(3) cm (ឬ 5 sqrt(3)/2 cm) (1 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'medium', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11442, 'គេឱ្យ \(\sin \alpha + \cos \alpha = \sqrt{2}\)។
ក. គណនាតម្លៃនៃ \(\sin \alpha \cos \alpha\)។
ខ. គណនាតម្លៃនៃ \(\sin^3 \alpha + \cos^3 \alpha\) និង \(\sin^4 \alpha + \cos^4 \alpha\)។', NULL, '[]', 0, NULL, 5, 'writing', 'លើកជាការេ: (sin α + cos α)^2 = 1 + 2 sin α cos α = (sqrt(2))^2 = 2 (1 ពិន្ទុ)
ទាញរក sin α cos α = (2 - 1)/2 = 1/2 (1 ពិន្ទុ)
ប្រើរូបមន្ត a^3 + b^3 = (a + b)(a^2 - ab + b^2) = (sqrt(2))(1 - 1/2) = sqrt(2)/2 (1.5 ពិន្ទុ)
ប្រើរូបមន្ត a^4 + b^4 = (a^2 + b^2)^2 - 2a^2 b^2 = 1^2 - 2(1/2)^2 = 1 - 1/2 = 1/2 (1 ពិន្ទុ)
សន្និដ្ឋាន: sin α cos α = 1/2, sin^3 α + cos^3 α = sqrt(2)/2, sin^4 α + cos^4 α = 1/2 (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11443, 'ដោះស្រាយសមីការត្រីកោណមាត្រខាងក្រោមចំពោះមុំ \(\alpha \in [0^\circ, 180^\circ]\) ៖
\(2\cos^2 \alpha - 3\cos \alpha + 1 = 0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់អថេរជំនួយ t = cos α ដែល -1 <= t <= 1: 2t^2 - 3t + 1 = 0 (1.5 ពិន្ទុ)
រកឫសសមីការដឺក្រេទី 2: មាន a + b + c = 2 - 3 + 1 = 0 នាំឱ្យ t_1 = 1, t_2 = 1/2 (1.5 ពិន្ទុ)
ករណី t = 1: cos α = 1 នាំឱ្យ α = 0° (1 ពិន្ទុ)
ករណី t = 1/2: cos α = 1/2 នាំឱ្យ α = 60° (1 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11444, 'ត្រីកោណកែង \(ABC\) មួយកែងត្រង់ \(A\) មានមុំ \(\angle B = 60^\circ\) និងបរិមាត្រស្មើនឹង \(6 + 2\sqrt{3}\text{ cm}\)។
រកប្រវែងជ្រុងទាំងបី \(a, b, c\) នៃត្រីកោណនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាមអនុគមន៍ត្រីកោណមាត្រក្នុងត្រីកោណកែង: b = AC = a * sin 60° = a * sqrt(3)/2 (1.5 ពិន្ទុ)
ជ្រុង c = AB = a * cos 60° = a * (1/2) (1 ពិន្ទុ)
សរសេរសមីការបរិមាត្រ: a + b + c = a + a/2 + a*sqrt(3)/2 = a(3 + sqrt(3))/2 = 6 + 2 sqrt(3) (1 ពិន្ទុ)
ទាញរក a: a = 2 * 2(3 + sqrt(3)) / (3 + sqrt(3)) = 4 cm (1 ពិន្ទុ)
សន្និដ្ឋាន: a = 4 cm, b = 2 sqrt(3) cm, c = 2 cm (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11445, 'ស្រាយបញ្ជាក់ថាចំពោះគ្រប់មុំស្រួច \(\alpha\) ដែល \(\alpha \ne 45^\circ\) ៖
\(\dfrac{1}{1 - \tan \alpha} - \dfrac{1}{1 + \tan \alpha} = \dfrac{2\tan \alpha}{1 - \tan^2 \alpha}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរភាគបែងរួមនៃអង្គខាងឆ្វេង: (1 - tan α)(1 + tan α) = 1 - tan^2 α (1.5 ពិន្ទុ)
តម្រូវភាគបែង: ភាគយក = (1 + tan α) - (1 - tan α) (1.5 ពិន្ទុ)
គណនាបង្រួមភាគយក: 1 + tan α - 1 + tan α = 2 tan α (1 ពិន្ទុ)
ទាញបានអង្គខាងឆ្វេង = 2 tan α / (1 - tan^2 α) = អង្គខាងស្តាំ (ពិត) (1 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'hard', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11446, 'សិស្សម្នាក់ចង់វាស់កម្ពស់អគារសិក្សាដោយប្រើឧបករណ៍ក្លីណូម៉ែត្រ (Clinometer)។
គាត់ឈរនៅចម្ងាយ \(30\text{ m}\) ពីជើងអគារ ហើយមើលទៅកំពូលអគារឃើញមុំងើប \(30^\circ\)។ កម្ពស់ពីដីទៅដល់ភ្នែកគាត់គឺ \(1.5\text{ m}\)។
ក. សរសេរទំនាក់ទំនងត្រីកោណមាត្រកំណត់កម្ពស់ផ្នែកខាងលើ \(h_1\) ធៀបនឹងកម្ពស់ភ្នែក។
ខ. គណនាកម្ពស់សរុបនៃអគារសិក្សានោះ (យក \(\sqrt{3} \approx 1.732\))។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់គំរូធរណីមាត្រ: ត្រីកោណកែងមានជ្រុងជាប់ d = 30 m មុំងើប θ = 30° និងជ្រុងឈម h_1 (1.5 ពិន្ទុ)
សរសេររូបមន្ត: tan 30° = h_1 / d នាំឱ្យ h_1 = d * tan 30° (1 ពិន្ទុ)
គណនា h_1 = 30 * (sqrt(3)/3) = 10 sqrt(3) ≈ 10 * 1.732 = 17.32 m (1 ពិន្ទុ)
គណនាកម្ពស់សរុប: H = h_1 + h_ភ្នែក = 17.32 + 1.5 = 18.82 m (1 ពិន្ទុ)
សន្និដ្ឋានថាអគារសិក្សាមានកម្ពស់ប្រហែល 18.82 ម៉ែត្រ (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11447, 'ប៉មទូរគមនាគមន៍មួយត្រូវបានទប់លំនឹងដោយខ្សែខ្សែកាបដែកចំនួន 3 ខ្សែភ្ជាប់ពីកំពូលប៉មមកដី។
ខ្សែនីមួយៗត្រូវបានបោះយុថ្កានៅលើដីចម្ងាយ \(24\text{ m}\) ពីជើងប៉ម ហើយបង្កើតបានមុំ \(60^\circ\) ជាមួយដីរាបស្មើ។
ក. គណនាកម្ពស់នៃប៉មទូរគមនាគមន៍ (គិតជា \(\text{m}\))។
ខ. គណនាប្រវែងខ្សែខ្សែកាបនីមួយៗ និងប្រវែងខ្សែកាបសរុបដែលត្រូវប្រើសម្រាប់ខ្សែទាំង 3។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកម្ពស់ប៉ម: tan 60° = h / 24 នាំឱ្យ h = 24 * tan 60° = 24 sqrt(3) m (≈ 41.57 m) (1.5 ពិន្ទុ)
គណនាប្រវែងខ្សែនីមួយៗ L: cos 60° = 24 / L នាំឱ្យ L = 24 / cos 60° (1.5 ពិន្ទុ)
គណនា L = 24 / (1/2) = 48 m (1 ពិន្ទុ)
គណនាប្រវែងខ្សែកាបសរុបសម្រាប់ 3 ខ្សែ: L_សរុប = 3 * 48 = 144 m (1 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11448, 'អ្នកយាមបង្គោលភ្លើងហ្វារម្នាក់ស្ថិតនៅលើកំពូលច្រាំងថ្មចោទកម្ពស់ \(50\text{ m}\) ពីនីវ៉ូទឹកសមុទ្រ។ គាត់សម្លឹងឃើញទូកនេសាទមួយដោយមុំទម្លាក់ \(30^\circ\)។
ក. ពន្យល់អំពីទំនាក់ទំនងរវាងមុំទម្លាក់ពីបង្គោលភ្លើងហ្វារ និងមុំងើបពីទូកមកបង្គោលភ្លើងហ្វារ។
ខ. គណនាចម្ងាយផ្តេកពីទូកនេសាទមកជើងច្រាំងថ្មចោទ (យក \(\sqrt{3} \approx 1.732\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្យល់: មុំទម្លាក់និងមុំងើបជាមុំឆ្លាស់ក្នុងរវាងបន្ទាត់ផ្តេកស្របគ្នា ដូច្នេះមុំទាំងពីរមានទំហំស្មើគ្នាគឺ 30° (1.5 ពិន្ទុ)
កំណត់ទំនាក់ទំនងត្រីកោណមាត្រ: tan 30° = h / d ដែល h = 50 m ជាកម្ពស់ និង d ជាចម្ងាយផ្តេក (1 ពិន្ទុ)
ទាញរក d = h / tan 30° = 50 / (sqrt(3)/3) = 50 sqrt(3) m (1.5 ពិន្ទុ)
គណនាតម្លៃលេខ: d ≈ 50 * 1.732 = 86.6 m (1 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11449, 'ផ្លូវឡើងភ្នំមួយមានជម្រាលថេរដោយបង្កើតបានមុំ \(18^\circ\) ធៀបនឹងប្លង់ដេក។
ក. បើអ្នកឡើងភ្នំដើរបានចម្ងាយ \(1,500\text{ m}\) តាមផ្លូវជម្រាល តើគាត់បានឡើងកម្ពស់បញ្ឈរបានប៉ុន្មានម៉ែត្រ? (យក \(\sin 18^\circ \approx 0.3090\))
ខ. បើគាត់ចង់ឡើងដល់កំពូលភ្នំដែលមានកម្ពស់បញ្ឈរ \(618\text{ m}\) ខ្ពស់ជាងចំណុចចាប់ផ្តើម តើគាត់ត្រូវដើរតាមផ្លូវជម្រាលនេះចម្ងាយប៉ុន្មានម៉ែត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទំនាក់ទំនងកម្ពស់: h = L * sin 18° ដែល L ជាចម្ងាយតាមជម្រាល (1.5 ពិន្ទុ)
គណនាផ្នែក ក: h = 1500 * 0.3090 = 463.5 m (1.5 ពិន្ទុ)
សរសេរទំនាក់ទំនងរកចម្ងាយ: L_top = H / sin 18° = 618 / 0.3090 (1 ពិន្ទុ)
គណនាផ្នែក ខ: L_top = 2000 m (ឬ 2 km) (1 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11450, 'បាល់ឡុងហោះមួយកំពុងហោះលើអាកាស។ អ្នកសង្កេតពីរនាក់ឈរនៅចំណុច \(A\) និង \(B\) លើដីរាបស្មើចម្ងាយ \(1,000\text{ m}\) ពីគ្នា ដោយបាល់ឡុងស្ថិតនៅចន្លោះអ្នកទាំងពីរក្នុងប្លង់បញ្ឈរតែមួយ។
អ្នកនៅ \(A\) មើលឃើញបាល់ឡុងដោយមុំងើប \(45^\circ\) រីឯអ្នកនៅ \(B\) មើលឃើញដោយមុំងើប \(60^\circ\)។
ក. តាង \(h\) ជាកម្ពស់បាល់ឡុងពីដី។ បង្ហាញទំនាក់ទំនងរវាងចម្ងាយ \(AB\) និងកម្ពស់ \(h\)។
ខ. គណនាកម្ពស់ \(h\) នៃបាល់ឡុង (យក \(\sqrt{3} \approx 1.732\))។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង H ជាចំណុចលើដីចំពីក្រោមបាល់ឡុង: AH = h / tan 45° = h, BH = h / tan 60° = h / sqrt(3) (1.5 ពិន្ទុ)
សរសេរសមីការចម្ងាយសរុប: AB = AH + BH = h + h / sqrt(3) = h(1 + 1/sqrt(3)) = 1000 m (1 ពិន្ទុ)
ទាញរក h: h(sqrt(3) + 1)/sqrt(3) = 1000 នាំឱ្យ h = 1000 sqrt(3) / (sqrt(3) + 1) (1 ពិន្ទុ)
បំបាត់រ៉ាឌីកាល់: h = 1000 sqrt(3)(sqrt(3) - 1) / 2 = 500(3 - sqrt(3)) ≈ 500(3 - 1.732) = 500(1.268) = 634 m (1 ពិន្ទុ)
សន្និដ្ឋានថាកម្ពស់បាល់ឡុងគឺប្រហែល 634 ម៉ែត្រ (0.5 ពិន្ទុ)', 'ផលធៀបត្រីកោណមាត្រ', 'pisa', 0, '10', 'ផលធៀបត្រីកោណមាត្រ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
