INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11501, 'ក្នុងគ្រប់ត្រីកោណ \(ABC\) ដែលមានកាំរង្វង់ចារឹកក្រៅ \(R\) តើរូបមន្តទ្រឹស្តីបទស៊ីនុសមួយណាត្រឹមត្រូវ?', 'g10-cbe284fea7.svg', '["\\(a \\sin A = b \\sin B = c \\sin C = 2R\\)", "\\(\\dfrac{\\sin A}{a} = \\dfrac{\\sin B}{b} = \\dfrac{\\sin C}{c} = 2R\\)", "\\(\\dfrac{a}{\\sin A} = \\dfrac{b}{\\sin B} = \\dfrac{c}{\\sin C} = R\\)", "\\(\\dfrac{a}{\\sin A} = \\dfrac{b}{\\sin B} = \\dfrac{c}{\\sin C} = 2R\\)"]', 3, NULL, 1, 'mcq', '\frac{a}{\sin A} = \frac{b}{\sin B} = \frac{c}{\sin C} = 2R', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-0a5ff15dea.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11502, 'ក្នុងត្រីកោណ \(ABC\) តើរូបមន្តទ្រឹស្តីបទកូស៊ីនុសសម្រាប់ជ្រុង \(a\) មួយណាត្រឹមត្រូវ?', 'g10-0a5ff15dea.svg', '["\\(a^2 = (b + c)^2 - 2bc \\cos A\\)", "\\(a^2 = b^2 - c^2 - 2bc \\cos A\\)", "\\(a^2 = b^2 + c^2 + 2bc \\cos A\\)", "\\(a^2 = b^2 + c^2 - 2bc \\cos A\\)"]', 3, NULL, 1, 'mcq', 'a^2 = b^2 + c^2 - 2bc \cos A', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-2f5a4ae529.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11503, 'រូបមន្តផ្ទៃក្រឡាត្រីកោណ \(ABC\) តាមប្រវែងជ្រុងពីរ \(a, b\) និងមុំកៀប \(C\) គឺ ៖', 'g10-2f5a4ae529.svg', '["\\(S = \\dfrac{1}{2}ab \\cos C\\)", "\\(S = ab \\sin C\\)", "\\(S = \\dfrac{1}{2}ab \\sin C\\)", "\\(S = \\dfrac{1}{2}(a + b)\\sin C\\)"]', 2, NULL, 1, 'mcq', 'S = \frac{1}{2}ab \sin C', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11504, 'ក្នុងត្រីកោណ \(ABC\) មាន \(\angle A = 45^\circ\) និង \(\angle B = 75^\circ\)។ តើមុំ \(\angle C\) មានរង្វាស់ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(80^\\circ\\)", "\\(50^\\circ\\)", "\\(70^\\circ\\)", "\\(60^\\circ\\)"]', 3, NULL, 1, 'mcq', '\angle C = 180^\circ - (45^\circ + 75^\circ) = 60^\circ', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11505, 'ក្នុងត្រីកោណ \(ABC\) មាន \(a = 6\text{ cm}\) និង \(\sin A = \dfrac{1}{2}\)។ គណនាកាំ \(R\) នៃរង្វង់ចារឹកក្រៅត្រីកោណ។', NULL, '["\\(6\\text{ cm}\\)", "\\(24\\text{ cm}\\)", "\\(3\\text{ cm}\\)", "\\(12\\text{ cm}\\)"]', 0, NULL, 1, 'mcq', '2R = \frac{a}{\sin A} = \frac{6}{1/2} = 12 \implies R = 6\text{ cm}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11506, 'ក្នុងត្រីកោណ \(ABC\) បើស្គាល់ប្រវែងជ្រុងទាំងបី \(a, b, c\) តើយើងគួរប្រើទ្រឹស្តីបទអ្វីដើម្បីគណនារង្វាស់មុំ?', NULL, '["\\(\\text{ទ្រឹស្តីបទតាល់ស}\\)", "\\(\\text{ទ្រឹស្តីបទកូស៊ីនុស}\\)", "\\(\\text{ទ្រឹស្តីបទពីតាករតែមួយមុខ}\\)", "\\(\\text{រូបមន្តហេរ៉ុង}\\)"]', 1, NULL, 1, 'mcq', '\cos A = \frac{b^2 + c^2 - a^2}{2bc}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11507, 'រូបមន្តហេរ៉ុង (Heron) សម្រាប់គណនាផ្ទៃក្រឡាត្រីកោណតាមកន្លះបរិមាត្រ \(p\) គឺ ៖', NULL, '["\\(S = p\\sqrt{(p - a)(p - b)(p - c)}\\)", "\\(S = \\sqrt{p(a + b + c)}\\)", "\\(S = \\sqrt{p(p - a)(p - b)(p - c)}\\)", "\\(S = \\sqrt{(p - a)(p - b)(p - c)}\\)"]', 2, NULL, 1, 'mcq', 'S = \sqrt{p(p-a)(p-b)(p-c)} \text{ ដែល } p = \frac{a+b+c}{2}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11508, 'ត្រីកោណមួយមានកន្លះបរិមាត្រ \(p = 10\text{ cm}\) និងកាំរង្វង់ចារឹកក្នុង \(r = 3\text{ cm}\)។ គណនាផ្ទៃក្រឡាត្រីកោណនោះ។', NULL, '["\\(20\\text{ cm}^2\\)", "\\(15\\text{ cm}^2\\)", "\\(60\\text{ cm}^2\\)", "\\(30\\text{ cm}^2\\)"]', 3, NULL, 1, 'mcq', 'S = pr = 10 \times 3 = 30\text{ cm}^2', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11509, 'ក្នុងត្រីកោណ \(ABC\) មាន \(a = 8\text{ cm},\; b = 10\text{ cm}\) និង \(\angle C = 30^\circ\)។ គណនាផ្ទៃក្រឡា \(S\)។', NULL, '["\\(40\\text{ cm}^2\\)", "\\(20\\sqrt{3}\\text{ cm}^2\\)", "\\(20\\text{ cm}^2\\)", "\\(10\\text{ cm}^2\\)"]', 2, NULL, 1, 'mcq', 'S = \frac{1}{2}(8)(10)\sin 30^\circ = 40 \times \frac{1}{2} = 20\text{ cm}^2', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11510, 'រូបមន្តផ្ទៃក្រឡាត្រីកោណ \(ABC\) តាមប្រវែងជ្រុងទាំងបី និងកាំ \(R\) នៃរង្វង់ចារឹកក្រៅគឺ ៖', NULL, '["\\(S = \\dfrac{abc}{2R}\\)", "\\(S = \\dfrac{abc}{R}\\)", "\\(S = \\dfrac{4R}{abc}\\)", "\\(S = \\dfrac{abc}{4R}\\)"]', 3, NULL, 1, 'mcq', 'S = \frac{abc}{4R}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11511, 'ក្នុងត្រីកោណ \(ABC\) មាន \(\angle A = 30^\circ,\; \angle B = 45^\circ\) និងជ្រុង \(a = 8\text{ cm}\)។ គណនាប្រវែងជ្រុង \(b\)។', NULL, '["\\(8\\sqrt{2}\\text{ cm}\\)", "\\(16\\text{ cm}\\)", "\\(4\\sqrt{2}\\text{ cm}\\)", "\\(8\\sqrt{3}\\text{ cm}\\)"]', 0, NULL, 2, 'mcq', '\frac{b}{\sin 45^\circ} = \frac{8}{\sin 30^\circ} \implies b = \frac{8 \times \frac{\sqrt{2}}{2}}{\frac{1}{2}} = 8\sqrt{2}\text{ cm}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11512, 'ក្នុងត្រីកោណ \(ABC\) មាន \(b = 6\text{ cm},\; c = 10\text{ cm}\) និង \(\angle A = 60^\circ\)។ គណនាប្រវែងជ្រុង \(a\)។', NULL, '["\\(\\sqrt{136}\\text{ cm}\\)", "\\(14\\text{ cm}\\)", "\\(8\\text{ cm}\\)", "\\(2\\sqrt{19}\\text{ cm}\\)"]', 3, NULL, 2, 'mcq', 'a^2 = 36 + 100 - 2(6)(10)\cos 60^\circ = 136 - 60 = 76 \implies a = \sqrt{76} = 2\sqrt{19}\text{ cm}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
