INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11513, 'ត្រីកោណមួយមានប្រវែងជ្រុងទាំងបី \(a = 13,\; b = 14,\; c = 15\)។ គណនាផ្ទៃក្រឡា \(S\) នៃត្រីកោណនេះ។', 'g10-3827c9b006.svg', '["\\(84\\)", "\\(80\\)", "\\(96\\)", "\\(90\\)"]', 0, NULL, 2, 'mcq', 'p = \frac{13+14+15}{2} = 21; S = \sqrt{21 \times 8 \times 7 \times 6} = \sqrt{7056} = 84', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11514, 'ក្នុងត្រីកោណ \(ABC\) មាន \(a = 6\text{ cm},\; b = 8\text{ cm}\) និងផ្ទៃក្រឡា \(S = 12\sqrt{3}\text{ cm}^2\)។ រកទំហំមុំស្រួច \(\angle C\)។', NULL, '["\\(75^\\circ\\)", "\\(60^\\circ\\)", "\\(30^\\circ\\)", "\\(45^\\circ\\)"]', 1, NULL, 2, 'mcq', 'S = \frac{1}{2}ab \sin C = 24 \sin C = 12\sqrt{3} \implies \sin C = \frac{\sqrt{3}}{2} \implies C = 60^\circ', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11515, 'ត្រីកោណ \(ABC\) មួយមានប្រវែងជ្រុង \(a = 4\text{ cm},\; b = 4\sqrt{3}\text{ cm},\; c = 8\text{ cm}\)។ តើ \(\triangle ABC\) ជាត្រីកោណប្រភេទអ្វី?', NULL, '["\\(\\text{ត្រីកោណកែងត្រង់ } C\\)", "\\(\\text{ត្រីកោណសមបាត}\\)", "\\(\\text{ត្រីកោណសម័ង្ស}\\)", "\\(\\text{ត្រីកោណកែងត្រង់ } A\\)"]', 0, NULL, 2, 'mcq', 'a^2 + b^2 = 16 + 48 = 64 = c^2 \implies \text{កែងត្រង់ } C', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11516, 'អ្នកវាស់ដីម្នាក់ចង់រកចម្ងាយឆ្លងកាត់ស្រះទឹកពីចំណុច \(A\) ទៅ \(B\)។ គាត់ឈរនៅចំណុច \(C\) ហើយវាស់បាន \(CA = 50\text{ m},\; CB = 70\text{ m}\) និងមុំ \(\angle ACB = 60^\circ\)។ គណនាចម្ងាយ \(AB\)។', NULL, '["\\(10\\sqrt{39}\\text{ m}\\)", "\\(65\\text{ m}\\)", "\\(10\\sqrt{74}\\text{ m}\\)", "\\(60\\text{ m}\\)"]', 0, NULL, 2, 'mcq', 'c^2 = 2500 + 4900 - 2(50)(70)(0.5) = 7400 - 3500 = 3900 \implies c = 10\sqrt{39}\text{ m}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11517, 'ក្នុងត្រីកោណ \(ABC\) មាន \(a = 10\text{ cm}\) និង \(\angle A = 45^\circ\)។ គណនាកាំ \(R\) នៃរង្វង់ចារឹកក្រៅត្រីកោណ។', NULL, '["\\(5\\text{ cm}\\)", "\\(10\\text{ cm}\\)", "\\(5\\sqrt{2}\\text{ cm}\\)", "\\(10\\sqrt{2}\\text{ cm}\\)"]', 2, NULL, 2, 'mcq', '2R = \frac{10}{\sin 45^\circ} = \frac{10}{\sqrt{2}/2} = 10\sqrt{2} \implies R = 5\sqrt{2}\text{ cm}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11518, 'ក្នុងត្រីកោណ \(ABC\) មានរង្វាស់ជ្រុង \(a = 5,\; b = 7,\; c = 8\)។ គណនាតម្លៃនៃ \(\cos C\)។', NULL, '["\\(\\dfrac{1}{5}\\)", "\\(\\dfrac{3}{7}\\)", "\\(\\dfrac{1}{7}\\)", "\\(\\dfrac{2}{7}\\)"]', 2, NULL, 2, 'mcq', '\cos C = \frac{5^2 + 7^2 - 8^2}{2(5)(7)} = \frac{25 + 49 - 64}{70} = \frac{10}{70} = \frac{1}{7}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11519, 'ត្រីកោណមួយមានប្រវែងជ្រុង \(a = 7,\; b = 8,\; c = 9\)។ គណនាផ្ទៃក្រឡា \(S\) នៃត្រីកោណនេះ។', NULL, '["\\(24\\sqrt{5}\\)", "\\(15\\sqrt{3}\\)", "\\(12\\sqrt{5}\\)", "\\(28\\)"]', 2, NULL, 2, 'mcq', 'p = 12; S = \sqrt{12(5)(4)(3)} = \sqrt{720} = 12\sqrt{5}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11520, 'ត្រីកោណមួយមានបរិមាត្រ \(36\text{ cm}\) និងផ្ទៃក្រឡា \(54\text{ cm}^2\)។ គណនាកាំ \(r\) នៃរង្វង់ចារឹកក្នុងត្រីកោណ។', NULL, '["\\(4.5\\text{ cm}\\)", "\\(6\\text{ cm}\\)", "\\(3\\text{ cm}\\)", "\\(1.5\\text{ cm}\\)"]', 2, NULL, 2, 'mcq', 'p = 36/2 = 18\text{ cm} \implies r = \frac{S}{p} = \frac{54}{18} = 3\text{ cm}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11521, 'ក្នុងត្រីកោណ \(ABC\) មាន \(\angle B = 60^\circ,\; \angle C = 45^\circ\) និង \(b = 6\text{ cm}\)។ គណនាប្រវែងជ្រុង \(c\)។', NULL, '["\\(3\\sqrt{2}\\text{ cm}\\)", "\\(4\\sqrt{2}\\text{ cm}\\)", "\\(2\\sqrt{6}\\text{ cm}\\)", "\\(3\\sqrt{6}\\text{ cm}\\)"]', 2, NULL, 2, 'mcq', 'c = \frac{b \sin 45^\circ}{\sin 60^\circ} = \frac{6 \times (\sqrt{2}/2)}{\sqrt{3}/2} = \frac{6\sqrt{2}}{\sqrt{3}} = 2\sqrt{6}\text{ cm}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11522, 'ក្នុងត្រីកោណ \(ABC\) មានជ្រុង \(a = 7,\; b = 5,\; c = 6\)។ គណនា \(\cos A\)។', NULL, '["\\(\\dfrac{3}{10}\\)", "\\(\\dfrac{2}{5}\\)", "\\(\\dfrac{1}{6}\\)", "\\(\\dfrac{1}{5}\\)"]', 3, NULL, 2, 'mcq', '\cos A = \frac{b^2 + c^2 - a^2}{2bc} = \frac{25 + 36 - 49}{60} = \frac{12}{60} = \frac{1}{5}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11523, 'ប្រលេឡូក្រាម \(ABCD\) មួយមានជ្រុងពីរជាប់គ្នា \(AB = 6\text{ cm},\; AD = 8\text{ cm}\) និងមុំ \(\angle A = 60^\circ\)។ គណនាផ្ទៃក្រឡាប្រលេឡូក្រាមនោះ។', NULL, '["\\(24\\text{ cm}^2\\)", "\\(48\\text{ cm}^2\\)", "\\(24\\sqrt{3}\\text{ cm}^2\\)", "\\(12\\sqrt{3}\\text{ cm}^2\\)"]', 2, NULL, 2, 'mcq', 'S = AB \times AD \times \sin A = 6 \times 8 \times \frac{\sqrt{3}}{2} = 24\sqrt{3}\text{ cm}^2', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11524, 'ក្នុងត្រីកោណ \(ABC\) មាន \(a = 4,\; b = 6\) និងមុំទាល \(\angle C = 120^\circ\)។ គណនាប្រវែងជ្រុង \(c\)។', NULL, '["\\(10\\)", "\\(\\sqrt{52}\\)", "\\(2\\sqrt{7}\\)", "\\(2\\sqrt{19}\\)"]', 3, NULL, 2, 'mcq', 'c^2 = 16 + 36 - 2(4)(6)\cos 120^\circ = 52 - 48(-1/2) = 52 + 24 = 76 \implies c = 2\sqrt{19}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11525, 'ក្នុងត្រីកោណ \(ABC\) បើគេមានទំនាក់ទំនង \(a^2 = b^2 + c^2 + bc\) នោះរង្វាស់មុំ \(\angle A\) ស្មើនឹង ៖', NULL, '["\\(120^\\circ\\)", "\\(135^\\circ\\)", "\\(60^\\circ\\)", "\\(150^\\circ\\)"]', 0, NULL, 3, 'mcq', '-2bc \cos A = bc \implies \cos A = -1/2 \implies A = 120^\circ', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11526, 'ក្នុងត្រីកោណ \(ABC\) បើគេមាន \(\dfrac{a}{\cos A} = \dfrac{b}{\cos B}\) នោះ \(\triangle ABC\) ជាត្រីកោណអ្វី?', NULL, '["\\(\\text{ត្រីកោណសម័ង្ស}\\)", "\\(\\text{ត្រីកោណមិនអាចកំណត់បាន}\\)", "\\(\\text{ត្រីកោណសមបាតដែលមាន } a = b\\)", "\\(\\text{ត្រីកោណកែង}\\)"]', 2, NULL, 3, 'mcq', '\frac{2R\sin A}{\cos A} = \frac{2R\sin B}{\cos B} \implies \tan A = \tan B \implies A = B \implies a = b', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11527, 'ត្រីកោណ \(ABC\) មានជ្រុង \(a = 13,\; b = 14,\; c = 15\) និងផ្ទៃក្រឡា \(S = 84\)។ គណនាកាំ \(R\) នៃរង្វង់ចារឹកក្រៅត្រីកោណ។', NULL, '["\\(\\dfrac{65}{8}\\)", "\\(\\dfrac{65}{4}\\)", "\\(\\dfrac{35}{4}\\)", "\\(8\\)"]', 0, NULL, 3, 'mcq', 'R = \frac{abc}{4S} = \frac{13 \times 14 \times 15}{4 \times 84} = \frac{2730}{336} = \frac{65}{8} = 8.125', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11528, 'ក្នុងត្រីកោណ \(ABC\) មាន \(b = 8,\; c = 5\) និងផ្ទៃក្រឡា \(S = 10\sqrt{3}\)។ បើមុំ \(\angle A\) ជាមុំទាល ចូរគណនាប្រវែងជ្រុង \(a\)។', NULL, '["\\(\\sqrt{109}\\)", "\\(\\sqrt{89}\\)", "\\(\\sqrt{129}\\)", "\\(\\sqrt{49} = 7\\)"]', 2, NULL, 3, 'mcq', 'S = 20\sin A = 10\sqrt{3} \implies \sin A = \sqrt{3}/2 \implies A = 120^\circ \implies a^2 = 64 + 25 - 2(40)(-1/2) = 129 \implies a = \sqrt{129}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11529, 'ក្នុងត្រីកោណ \(ABC\) មាន \(a = 6,\; b = 8,\; c = 10\)។ គណនាប្រវែងមេដ្យាន \(m_a\) គូសចេញពីកំពូល \(A\) ទៅកាន់ជ្រុង \(a\)។', NULL, '["\\(5\\)", "\\(2\\sqrt{17}\\)", "\\(\\sqrt{85}\\)", "\\(\\sqrt{73}\\)"]', 3, NULL, 3, 'mcq', 'm_a^2 = \frac{2b^2 + 2c^2 - a^2}{4} = \frac{2(64) + 2(100) - 36}{4} = \frac{292}{4} = 73 \implies m_a = \sqrt{73}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11530, 'ក្នុងត្រីកោណ \(ABC\) មាន \(\angle A = 60^\circ,\; b = 5,\; c = 8\)។ គណនាប្រវែងកន្លះបន្ទាត់ពុះមុំក្នុង \(l_A\)។', NULL, '["\\(\\dfrac{40}{13}\\)", "\\(\\dfrac{80\\sqrt{3}}{13}\\)", "\\(\\dfrac{40\\sqrt{3}}{13}\\)", "\\(\\dfrac{20\\sqrt{3}}{13}\\)"]', 2, NULL, 3, 'mcq', 'l_A = \frac{2bc\cos(A/2)}{b + c} = \frac{2(5)(8)\cos 30^\circ}{13} = \frac{80 \times \frac{\sqrt{3}}{2}}{13} = \frac{40\sqrt{3}}{13}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11531, 'ក្នុងត្រីកោណ \(ABC\) បើ \(\cos A = \dfrac{4}{5},\; \cos B = \dfrac{12}{13}\) (មុំស្រួចទាំងពីរ) នោះតម្លៃនៃ \(\sin C\) ស្មើនឹង ៖', NULL, '["\\(\\dfrac{56}{65}\\)", "\\(\\dfrac{63}{65}\\)", "\\(\\dfrac{16}{65}\\)", "\\(\\dfrac{33}{65}\\)"]', 0, NULL, 3, 'mcq', '\sin A = 3/5, \sin B = 5/13 \implies \sin C = \sin(A+B) = \sin A \cos B + \cos A \sin B = (3/5)(12/13) + (4/5)(5/13) = 56/65', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-a53b8273cf.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11532, 'ចំណុច \(A\) និង \(B\) ស្ថិតនៅត្រើយម្ខាងនៃទន្លេមានចម្ងាយ \(100\text{ m}\) ពីគ្នា។ ដើមឈើ \(C\) មួយស្ថិតនៅត្រើយម្ខាងទៀត។ អ្នកវាស់ដីវាស់ឃើញ \(\angle CAB = 60^\circ\) និង \(\angle CBA = 45^\circ\)។ គណនាចម្ងាយ \(AC\) (យក \(\sin 75^\circ \approx 0.966,\; \sin 45^\circ \approx 0.707\))។', 'g10-a53b8273cf.svg', '["\\(\\approx 81.6\\text{ m}\\)", "\\(\\approx 73.2\\text{ m}\\)", "\\(\\approx 92.5\\text{ m}\\)", "\\(\\approx 65.4\\text{ m}\\)"]', 1, NULL, 3, 'mcq', '\angle C = 180^\circ - (60^\circ + 45^\circ) = 75^\circ \implies AC = \frac{100 \sin 45^\circ}{\sin 75^\circ} \approx \frac{70.7}{0.966} \approx 73.2\text{ m}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11533, 'ស្ថានីយឆ្នេរពីរ \(A\) និង \(B\) ស្ថិតនៅចម្ងាយ \(30\text{ km}\) ពីគ្នា។ ស្ថានីយទាំងពីរទទួលបានសញ្ញាអាសន្នពីកប៉ាល់ \(S\) ដោយវាស់បានមុំ \(\angle SAB = 45^\circ\) និង \(\angle SBA = 60^\circ\)។ គណនាចម្ងាយពីស្ថានីយ \(A\) ទៅកាន់កប៉ាល់ \(S\) (យក \(\sin 60^\circ \approx 0.866,\; \sin 75^\circ \approx 0.966\))។', NULL, '["\\(\\approx 31.2\\text{ km}\\)", "\\(\\approx 26.9\\text{ km}\\)", "\\(\\approx 22.5\\text{ km}\\)", "\\(\\approx 19.8\\text{ km}\\)"]', 1, NULL, 3, 'mcq', '\angle S = 75^\circ \implies SA = \frac{30 \sin 60^\circ}{\sin 75^\circ} \approx \frac{30 \times 0.866}{0.966} \approx 26.9\text{ km}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11534, 'កសិករម្នាក់មានដីស្រែរាងត្រីកោណដែលមានជ្រុងជាប់ថ្នល់ពីរប្រវែង \(60\text{ m}\) និង \(80\text{ m}\) ដោយផ្គុំបានមុំ \(60^\circ\) នៅត្រង់ផ្លូវបំបែក។ គណនាផ្ទៃក្រឡាដីស្រែនោះ (យក \(\sqrt{3} \approx 1.732\))។', NULL, '["\\(\\approx 2,078\\text{ m}^2\\)", "\\(\\approx 1,850\\text{ m}^2\\)", "\\(\\approx 2,400\\text{ m}^2\\)", "\\(\\approx 3,120\\text{ m}^2\\)"]', 0, NULL, 3, 'mcq', 'S = \frac{1}{2}(60)(80)\sin 60^\circ = 2400 \times \frac{\sqrt{3}}{2} = 1200\sqrt{3} \approx 1200 \times 1.732 = 2078.4\text{ m}^2', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11535, 'ប៉មសង្កេតការណ៍ភ្លើងព្រៃពីរ \(T_1\) និង \(T_2\) មានចម្ងាយ \(10\text{ km}\) ពីគ្នា។ ប៉មទាំងពីរប្រទះឃើញផ្សែងភ្លើងនៅចំណុច \(F\) ដោយវាស់បានមុំ \(\angle T_2 T_1 F = 40^\circ\) និង \(\angle T_1 T_2 F = 70^\circ\)។ តើផ្សែងភ្លើងនោះនៅឆ្ងាយពីប៉ម \(T_1\) ប៉ុន្មានគីឡូម៉ែត្រ?', NULL, '["\\(14.5\\text{ km}\\)", "\\(10\\text{ km}\\)", "\\(8\\text{ km}\\)", "\\(12\\text{ km}\\)"]', 1, NULL, 3, 'mcq', '\angle F = 180^\circ - (40^\circ + 70^\circ) = 70^\circ \implies \angle T_2 = \angle F = 70^\circ \implies \triangle T_1 T_2 F \text{ សមបាត } \implies T_1 F = T_1 T_2 = 10\text{ km}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11536, 'អ្នកវាស់ដីម្នាក់វាស់មុំងើបទៅកាន់កំពូលភ្នំពីចំណុច \(A\) ឃើញមុំ \(30^\circ\)។ គាត់ដើរទៅមុខតាមដីរាបស្មើចម្ងាយ \(400\text{ m}\) ដល់ចំណុច \(B\) ហើយវាស់មុំងើបឃើញ \(45^\circ\)។ គណនាកម្ពស់ភ្នំនោះ (យក \(\sqrt{3} \approx 1.732\))។', NULL, '["\\(\\approx 625\\text{ m}\\)", "\\(\\approx 400\\text{ m}\\)", "\\(\\approx 480\\text{ m}\\)", "\\(\\approx 546\\text{ m}\\)"]', 3, NULL, 3, 'mcq', 'h = \frac{400}{\cot 30^\circ - \cot 45^\circ} = \frac{400}{\sqrt{3} - 1} = \frac{400(\sqrt{3} + 1)}{2} = 200(1.732 + 1) = 546.4\text{ m}', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 1, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11537, 'ក្នុងត្រីកោណ \(ABC\) មាន \(b = 6\text{ cm},\; c = 10\text{ cm}\) និងមុំកៀប \(\angle A = 60^\circ\)។
ក. អនុវត្តទ្រឹស្តីបទកូស៊ីនុសដើម្បីគណនាប្រវែងជ្រុង \(a\)។
ខ. គណនាផ្ទៃក្រឡា \(S\) នៃត្រីកោណ \(ABC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តទ្រឹស្តីបទកូស៊ីនុស: a^2 = b^2 + c^2 - 2bc cos A (1.5 ពិន្ទុ)
ជំនួសតម្លៃលេខ: a^2 = 6^2 + 10^2 - 2(6)(10) cos 60° = 36 + 100 - 120(1/2) = 136 - 60 = 76 (1 ពិន្ទុ)
ទាញរកប្រវែងជ្រុង a = sqrt(76) = 2 sqrt(19) cm (1 ពិន្ទុ)
សរសេររូបមន្តផ្ទៃក្រឡា: S = (1/2) bc sin A = (1/2)(6)(10) sin 60° (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡា S = 30 * (sqrt(3)/2) = 15 sqrt(3) cm^2 (0.5 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'easy', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11538, 'ក្នុងត្រីកោណ \(ABC\) មាន \(\angle A = 45^\circ,\; \angle B = 60^\circ\) និងជ្រុង \(a = 10\text{ cm}\)។
ក. គណនារង្វាស់មុំ \(\angle C\)។
ខ. អនុវត្តទ្រឹស្តីបទស៊ីនុសដើម្បីគណនាប្រវែងជ្រុង \(b\)។
គ. គណនាកាំ \(R\) នៃរង្វង់ចារឹកក្រៅត្រីកោណ \(ABC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាមុំ C: C = 180° - (45° + 60°) = 75° (1 ពិន្ទុ)
សរសេរទ្រឹស្តីបទស៊ីនុស: b / sin B = a / sin A (1 ពិន្ទុ)
ទាញរក b = (a * sin 60°) / sin 45° = 10 * (sqrt(3)/2) / (sqrt(2)/2) = 10 sqrt(3) / sqrt(2) = 5 sqrt(6) cm (1.5 ពិន្ទុ)
គណនាកាំ R: 2R = a / sin A = 10 / (sqrt(2)/2) = 10 sqrt(2) (1 ពិន្ទុ)
សន្និដ្ឋាន R = 5 sqrt(2) cm (0.5 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11539, 'ត្រីកោណ \(ABC\) មួយមានប្រវែងជ្រុងទាំងបី \(a = 7\text{ cm},\; b = 8\text{ cm},\; c = 9\text{ cm}\)។
ក. គណនាកន្លះបរិមាត្រ \(p\) នៃត្រីកោណ។
ខ. ប្រើរូបមន្តហេរ៉ុងដើម្បីគណនាផ្ទៃក្រឡា \(S\) នៃត្រីកោណ។
គ. គណនាកាំ \(r\) នៃរង្វង់ចារឹកក្នុងត្រីកោណនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកន្លះបរិមាត្រ: p = (7 + 8 + 9) / 2 = 24 / 2 = 12 cm (1.5 ពិន្ទុ)
គណនាកត្តា: p - a = 5, p - b = 4, p - c = 3 (1 ពិន្ទុ)
អនុវត្តរូបមន្តហេរ៉ុង: S = sqrt(12 * 5 * 4 * 3) = sqrt(720) = 12 sqrt(5) cm^2 (1.5 ពិន្ទុ)
គណនាកាំរង្វង់ចារឹកក្នុង r = S / p = 12 sqrt(5) / 12 = sqrt(5) cm (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11540, 'ក្នុងត្រីកោណ \(ABC\) មាន \(b = 8\text{ cm},\; c = 6\text{ cm}\) និងមុំ \(\angle A = 120^\circ\)។
ក. គណនាប្រវែងជ្រុង \(a\)។
ខ. គណនាផ្ទៃក្រឡា \(S\) នៃត្រីកោណ \(ABC\)។
គ. គណនាប្រវែងកម្ពស់ \(h_a\) គូសចេញពីកំពូល \(A\) មកលើជ្រុង \(a\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា a^2 = 8^2 + 6^2 - 2(8)(6) cos 120° = 64 + 36 - 96(-1/2) = 100 + 48 = 148 (1.5 ពិន្ទុ)
ទាញរក a = sqrt(148) = 2 sqrt(37) cm (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡា S = (1/2) bc sin 120° = (1/2)(8)(6)(sqrt(3)/2) = 12 sqrt(3) cm^2 (1.5 ពិន្ទុ)
គណនាកម្ពស់ h_a = 2S / a = 24 sqrt(3) / (2 sqrt(37)) = 12 sqrt(3) / sqrt(37) = 12 sqrt(111)/37 cm (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11541, 'ដីចម្ការមួយមានរាងជាចតុកោណ \(ABCD\) ត្រូវបានពុះចែកជាពីរត្រីកោណដោយអង្កត់ទ្រូង \(AC\)។
គេដឹងថា ៖ ក្នុង \(\triangle ABC\) មាន \(AB = 40\text{ m},\; BC = 60\text{ m},\; \angle B = 60^\circ\);
ក្នុង \(\triangle ACD\) មាន \(CD = 50\text{ m},\; AD = 30\text{ m},\; \angle D = 60^\circ\)។
គណនាផ្ទៃក្រឡាសរុបនៃដីចម្ការនោះ (យក \(\sqrt{3} \approx 1.732\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផ្ទៃក្រឡា S_1 នៃ ត្រីកោណ ABC: S_1 = (1/2) * 40 * 60 * sin 60° = 1200 * (sqrt(3)/2) = 600 sqrt(3) m^2 (1.5 ពិន្ទុ)
គណនាផ្ទៃក្រឡា S_2 នៃ ត្រីកោណ ACD: S_2 = (1/2) * 50 * 30 * sin 60° = 750 * (sqrt(3)/2) = 375 sqrt(3) m^2 (1.5 ពិន្ទុ)
គណនាផ្ទៃក្រឡាសរុប: S = S_1 + S_2 = 600 sqrt(3) + 375 sqrt(3) = 975 sqrt(3) m^2 (1 ពិន្ទុ)
គណនាតម្លៃលេខ: S ≈ 975 * 1.732 = 1,688.7 m^2 (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'medium', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11542, 'ក្នុងគ្រប់ត្រីកោណ \(ABC\) ស្រាយបញ្ជាក់រូបមន្តម៉ូលវ៉េដ (Mollweide''s formula) ៖
\(\dfrac{a + b}{c} = \dfrac{\cos\dfrac{A - B}{2}}{\sin\dfrac{C}{2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើទ្រឹស្តីបទស៊ីនុស a = 2R sin A, b = 2R sin B, c = 2R sin C: (a + b)/c = (sin A + sin B) / sin C (1.5 ពិន្ទុ)
បំប្លែងផលបូកទៅជាផលគុណ: sin A + sin B = 2 sin((A+B)/2) cos((A-B)/2) (1.5 ពិន្ទុ)
ដោយ A + B + C = 180° នាំឱ្យ (A+B)/2 = 90° - C/2 ដូច្នេះ sin((A+B)/2) = cos(C/2) (1 ពិន្ទុ)
សរសេរ sin C = 2 sin(C/2) cos(C/2) ហើយសម្រួល 2 cos(C/2) នាំឱ្យបានសមភាពពិត (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11543, 'ត្រីកោណ \(ABC\) មានរង្វាស់ជ្រុងទាំងបី \(a = 13,\; b = 14,\; c = 15\)។
ក. គណនាផ្ទៃក្រឡា \(S\) និងកាំ \(R\) នៃរង្វង់ចារឹកក្រៅត្រីកោណ។
ខ. គណនាប្រវែងកម្ពស់ \(h_a\) និងប្រវែងមេដ្យាន \(m_a\) គូសទៅលើជ្រុង \(a\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា p = 21, S = sqrt(21 * 8 * 7 * 6) = 84 (1 ពិន្ទុ)
គណនា R = abc / (4S) = (13 * 14 * 15) / (4 * 84) = 2730 / 336 = 65/8 = 8.125 (1 ពិន្ទុ)
គណនាកម្ពស់ h_a = 2S / a = 2(84) / 14 = 168 / 14 = 12 (ជ្រុង a=14) (1.5 ពិន្ទុ)
គណនាមេដ្យាន m_a: m_a^2 = (2b^2 + 2c^2 - a^2)/4 = (2(225) + 2(169) - 196)/4 = (450 + 338 - 196)/4 = 592/4 = 148 (1 ពិន្ទុ)
សន្និដ្ឋាន m_a = sqrt(148) = 2 sqrt(37) (0.5 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11544, 'ក្នុងត្រីកោណ \(ABC\) មានជ្រុង \(a = 8\text{ cm},\; b = 10\text{ cm}\) និង \(\cos C = \dfrac{1}{4}\)។
ក. គណនាប្រវែងជ្រុង \(c\)។
ខ. គណនា \(\sin C\) រួចទាញរកផ្ទៃក្រឡា \(S\) នៃត្រីកោណ។
គ. គណនាកាំ \(R\) នៃរង្វង់ចារឹកក្រៅត្រីកោណ \(ABC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តទ្រឹស្តីបទកូស៊ីនុស: c^2 = 8^2 + 10^2 - 2(8)(10)(1/4) = 64 + 100 - 40 = 124 នាំឱ្យ c = sqrt(124) = 2 sqrt(31) cm (1.5 ពិន្ទុ)
គណនា sin C = sqrt(1 - (1/4)^2) = sqrt(15)/4 (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡា S = (1/2) ab sin C = (1/2)(8)(10)(sqrt(15)/4) = 10 sqrt(15) cm^2 (1 ពិន្ទុ)
គណនាកាំ R = c / (2 sin C) = (2 sqrt(31)) / (2 * sqrt(15)/4) = 4 sqrt(31) / sqrt(15) = 4 sqrt(465)/15 cm (1.5 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11545, 'ក្នុងត្រីកោណ \(ABC\) គេឱ្យទំនាក់ទំនងរវាងមុំ ៖ \(\sin^2 A + \sin^2 B = \sin^2 C\)។
ក. ដោយប្រើទ្រឹស្តីបទស៊ីនុស ចូរស្រាយបញ្ជាក់ថា \(\triangle ABC\) ជាត្រីកោណកែង។
ខ. បើគេដឹងបន្ថែមថា \(a = 6\text{ cm}\) និង \(b = 8\text{ cm}\) គណនាកាំ \(R\) និងកាំ \(r\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស sin A = a/2R, sin B = b/2R, sin C = c/2R នាំឱ្យ (a/2R)^2 + (b/2R)^2 = (c/2R)^2 (1.5 ពិន្ទុ)
សម្រួល 4R^2 បាន a^2 + b^2 = c^2 តាមច្រាសទ្រឹស្តីបទពីតាករ ត្រីកោណ ABC កែងត្រង់ C (1 ពិន្ទុ)
គណនាអ៊ីប៉ូតេនុស c = sqrt(6^2 + 8^2) = 10 cm នាំឱ្យកាំ R = c/2 = 5 cm (1 ពិន្ទុ)
គណនាកាំរង្វង់ចារឹកក្នុង r = (a + b - c)/2 = (6 + 8 - 10)/2 = 2 cm (1.5 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'hard', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11546, 'អ្នកវាស់ដីពីរនាក់ឈរនៅត្រើយម្ខាងនៃទន្លេត្រង់ចំណុច \(A\) និង \(B\) ដែលមានចម្ងាយ \(80\text{ m}\) ពីគ្នា។ ពួកគេសម្លឹងមើលបង្គោល \(C\) នៅត្រើយម្ខាងទៀត ដោយវាស់បានមុំ \(\angle CAB = 75^\circ\) និង \(\angle CBA = 60^\circ\)។
ក. គណនារង្វាស់មុំ \(\angle ACB\)។
ខ. គណនាចម្ងាយ \(AC\) ពីចំណុច \(A\) ទៅបង្គោល \(C\) (យក \(\sqrt{2} \approx 1.414,\; \sqrt{3} \approx 1.732\))។
គ. គណនាទទឹងទន្លេ (ចម្ងាយកែងពី \(C\) មកខ្សែបន្ទាត់ \(AB\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាមុំ ACB: C = 180° - (75° + 60°) = 45° (1 ពិន្ទុ)
អនុវត្តទ្រឹស្តីបទស៊ីនុស: AC / sin 60° = AB / sin 45° នាំឱ្យ AC = 80 * (sqrt(3)/2) / (sqrt(2)/2) = 80 sqrt(3)/sqrt(2) = 40 sqrt(6) m (1.5 ពិន្ទុ)
គណនាតម្លៃលេខ AC ≈ 40 * 2.449 = 97.96 m (0.5 ពិន្ទុ)
គណនាទទឹងទន្លេ h: h = AC * sin 75° ដោយ sin 75° = (sqrt(6) + sqrt(2))/4 (1 ពិន្ទុ)
គណនា h = 40 sqrt(6) * (sqrt(6) + sqrt(2))/4 = 10(6 + 2 sqrt(3)) = 60 + 20 sqrt(3) ≈ 60 + 34.64 = 94.64 m (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11547, 'ស្ថានីយបញ្ជូនសញ្ញាទូរស័ព្ទចំនួនបី \(A, B, C\) បង្កើតបានជាតំបន់ត្រីកោណគ្របដណ្តប់សញ្ញា ដោយមានចម្ងាយ \(AB = 12\text{ km},\; BC = 15\text{ km},\; AC = 9\text{ km}\)។
ក. ផ្ទៀងផ្ទាត់ថាតើ \(\triangle ABC\) ជាត្រីកោណកែងឬទេ?
ខ. គណនាផ្ទៃក្រឡាតំបន់គ្របដណ្តប់សញ្ញា \(S\) នៃត្រីកោណនេះ។
គ. គេចង់ដំឡើងអង់តែនមេមួយនៅចំណុច \(O\) ដែលនៅស្មើចម្ងាយពីស្ថានីយទាំងបី។ គណនាចម្ងាយ \(R\) ពីអង់តែនមេទៅស្ថានីយនីមួយៗ។', NULL, '[]', 0, NULL, 5, 'writing', 'ពិនិត្យលក្ខណៈពីតាករ: 9^2 + 12^2 = 81 + 144 = 225 = 15^2 នាំឱ្យត្រីកោណ ABC កែងត្រង់ A (1.5 ពិន្ទុ)
គណនាផ្ទៃក្រឡា: S = (1/2) * AC * AB = (1/2) * 9 * 12 = 54 km^2 (1.5 ពិន្ទុ)
កំណត់ទីតាំងអង់តែនមេ: ចំណុចស្មើចម្ងាយពីកំពូលទាំងបីគឺជាផ្ចិតរង្វង់ចារឹកក្រៅ O (1 ពិន្ទុ)
ក្នុងត្រីកោណកែង O ជាចំណុចកណ្តាលអ៊ីប៉ូតេនុស BC នាំឱ្យ R = BC / 2 = 15 / 2 = 7.5 km (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11548, 'យន្តហោះមួយហោះចេញពីទីក្រុង \(A\) ឆ្ពោះទៅទីក្រុង \(B\) ដែលនៅចម្ងាយ \(300\text{ km}\) ត្រង់ទិសខាងកើត។
ដើម្បីគេចពីពពកព្យុះ អ្នកបើកបរបានបង្វែរទិសងាក \(20^\circ\) ធៀបនឹងផ្លូវដើម ហើយហោះបានចម្ងាយ \(150\text{ km}\) ដល់ចំណុច \(C\) រួចហើយបត់ឆ្ពោះត្រង់ទៅទីក្រុង \(B\) វិញ។
ក. សរសេររូបមន្តទ្រឹស្តីបទកូស៊ីនុសកំណត់ចម្ងាយ \(CB\)។
ខ. គណនាចម្ងាយ \(CB\) ដែលនៅសល់ (យក \(\cos 20^\circ \approx 0.9397\))។
គ. គណនាចម្ងាយបន្ថែមដែលយន្តហោះត្រូវហោះលើសពីផ្លូវត្រង់ដើម។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទ្រឹស្តីបទកូស៊ីនុសក្នុងត្រីកោណ ABC: CB^2 = AC^2 + AB^2 - 2(AC)(AB) cos 20° (1.5 ពិន្ទុ)
ជំនួសតម្លៃលេខ: CB^2 = 150^2 + 300^2 - 2(150)(300)(0.9397) = 22500 + 90000 - 90000(0.9397) = 112500 - 84573 = 27927 (1.5 ពិន្ទុ)
ទាញរក CB = sqrt(27927) ≈ 167.1 km (1 ពិន្ទុ)
គណនាចម្ងាយបន្ថែម: d_បន្ថែម = (AC + CB) - AB = (150 + 167.1) - 300 = 317.1 - 300 = 17.1 km (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11549, 'កសិករម្នាក់ចង់ទិញដីចម្ការរាងត្រីកោណមួយកន្លែងដែលមានប្រវែងព្រំដីទាំងបីជ្រុង \(a = 35\text{ m},\; b = 40\text{ m},\; c = 45\text{ m}\)។
ក. គណនាកន្លះបរិមាត្រ \(p\) នៃដីចម្ការ។
ខ. គណនាផ្ទៃក្រឡា \(S\) នៃដីនោះតាមរូបមន្តហេរ៉ុង (គិតជា \(\text{m}^2\))។
គ. បើតម្លៃដីក្នុងតំបន់នោះគឺ 50 ដុល្លារក្នុងមួយម៉ែត្រការ៉េ គណនាតម្លៃប៉ាន់ស្មាននៃដីចម្ការនេះ (យក \(\sqrt{2} \approx 1.414\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកន្លះបរិមាត្រ: p = (35 + 40 + 45) / 2 = 120 / 2 = 60 m (1 ពិន្ទុ)
គណនាបណ្តាកត្តា: p - a = 25, p - b = 20, p - c = 15 (1 ពិន្ទុ)
អនុវត្តរូបមន្តហេរ៉ុង: S = sqrt(60 * 25 * 20 * 15) = sqrt(450,000) = 300 sqrt(5) m^2 (ឬ sqrt(60*25*20*15) = sqrt(450000) = 670.82 m^2) (1.5 ពិន្ទុ)
គណនាតម្លៃលេខផ្ទៃក្រឡា: S ≈ 300 * 2.236 = 670.8 m^2 (0.5 ពិន្ទុ)
គណនាតម្លៃដីសរុប: តម្លៃ = 670.8 * 50 = 33,540 ដុល្លារ (1 ពិន្ទុ)', 'ការអនុវត្តផលធៀបត្រីកោណ', 'pisa', 0, '10', 'ការអនុវត្តផលធៀបត្រីកោណ', 'ជំពូកទី 5 : ផលធៀបត្រីកោណមាត្រ', NULL, 0);
